#pragma once
// ADM -> modified-harmonic contact transformation, c.o.m. two-body, generated by tests/proto_admpn/derive_contact.py
// (2026-10-21). x_h = x + (G M / c^4) [(a1 p^2 + a2 pr^2 + a3 u) n + a4 pr p]
//                     + (G M / c^6) [(b1 p^4 + b2 p^2 pr^2 + b3 pr^4 + b4 p^2 u + b5 pr^2 u + b6 u^2) n + (b7 p^2 + b8 pr^2 + b9 u) pr p]
// with u = G M / r, p per reduced mass. The over-determined system (24 equations for 4 unknowns at 2PN, 24 for 9 at
// 3PN) is consistent: the DJS 3PN Hamiltonian and Blanchet's MH 3PN acceleration describe the same dynamics. Test-mass
// check: a3(nu = 0) = 1/4 is the isotropic -> harmonic Schwarzschild radius r_h = r_iso + (G M)^2 / (4 r_iso c^4).
#include "adm_pn.h"
inline admpn::ContactCoeffs admpn::contact_coeffs(double nu) {
    ContactCoeffs K{};
    const double pi2 = M_PI * M_PI, nu2 = nu * nu;
    K.a[0] = 5.0 / 8.0 * nu;
    K.a[1] = -1.0 / 8.0 * nu;
    K.a[2] = 3.0 * nu + 1.0 / 4.0;
    K.a[3] = -9.0 / 4.0 * nu;
    K.b[0] = 0.5 * nu2 - 1.0 / 8.0 * nu;
    K.b[1] = 9.0 / 16.0 * nu2 - 3.0 / 16.0 * nu;
    K.b[2] = -5.0 / 16.0 * nu2 + 1.0 / 16.0 * nu;
    K.b[3] = -7.0 / 8.0 * nu2 + 271.0 / 48.0 * nu;
    K.b[4] = 4.0 * nu2 - 125.0 / 48.0 * nu;
    K.b[5] = -2773.0 / 280.0 * nu - 21.0 / 32.0 * pi2 * nu;
    K.b[6] = -1.5 * nu2 + 1.0 / 8.0 * nu;
    K.b[7] = -29.0 / 24.0 * nu2 + 5.0 / 12.0 * nu;
    K.b[8] = 7.0 / 4.0 * nu2 - 5.0 / 6.0 * nu;
    return K;
}
